#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void){
    static char buf[1<<20];
    size_t len = fread(buf,1,sizeof buf-1,stdin);
    buf[len]=0;
    size_t i=0;
    while(i<=len){
        char *rec = buf+i;
        size_t l = strlen(rec);
        if(i+l>len && l==0 && i==len) break;
        printf("%d\n", atoi(rec));
        i += l+1;
        if(i>len) break;
    }
    return 0;
}
EOF
