mod cli;
use std::ffi::OsString;
use std::os::unix::ffi::OsStringExt;
use std::io::Read;
fn main(){
    let mut buf = Vec::new();
    std::io::stdin().read_to_end(&mut buf).unwrap();
    // split on NUL; a trailing NUL terminates the last record
    let mut recs: Vec<Vec<u8>> = Vec::new();
    let mut cur = Vec::new();
    for &b in &buf {
        if b == 0 { recs.push(std::mem::take(&mut cur)); } else { cur.push(b); }
    }
    if !cur.is_empty() { recs.push(cur); }
    let mut out = String::new();
    for r in recs {
        let args = vec![OsString::from("prog"), OsString::from_vec(r)];
        out.push_str(&format!("{}\n", cli::parse_n(args.into_iter())));
    }
    print!("{}", out);
}
EOF
