1	//! A from-scratch, dependency-free port of the earcut polygon triangulation
2	//! algorithm.
3	//!
4	//! Input is a polygon given as a list of rings — the first ring is the outer
5	//! contour, any remaining rings are holes. Output is a flat list of triangle
6	//! vertex indices into the concatenated ring coordinates.
7	
8	pub mod geom;
9	pub mod node;
10	pub mod triangulate;
11	pub mod zorder;
12	
13	pub use self::triangulate::Earcut;
14	
15	/// Triangulates `polygon` and returns the triangle index list.
16	pub fn earcut<R: AsRef<[[f64; 2]]>>(polygon: &[R]) -> Vec<u32> {
17	    let mut ec = Earcut::new();
18	    ec.run(polygon);
19	    ec.indices
20	}
